export const BODY: string = "\n<p>ایک Base64 اسٹرنگ آپ کے کلپ بورڈ، ای میل یا API جواب میں پڑی ہے، اور آپ کو اس میں موجود تصویر چاہیے۔ مرحلے معلوم ہوں تو تبدیلی میں تقریباً ایک منٹ لگتا ہے۔</p>\n<p>یہ رہنما Base64 کو تصویر میں بدلنا چار مرحلوں میں بتاتا ہے: اسٹرنگ پیسٹ کریں، پیش نظارہ جائزہ لیں، ڈاؤن لوڈ فارمیٹ چنیں اور فائل محفوظ کریں۔</p>\n<p>نہ کوئی سافٹ ویئر انسٹال کرنا ہے، نہ اکاؤنٹ بنانا ہے، اور کچھ بھی کہیں اپ لوڈ نہیں ہوتا۔ اسٹرنگ شروع سے آخر تک آپ کے براؤزر میں مقامی طور پر ڈی کوڈ ہوتی ہے۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>آپ کو Base64 اسٹرنگ خود چاہیے، مکمل کاپی شدہ۔ کٹی ہوئی اسٹرنگ ڈی کوڈ نہیں ہو سکتی، اس لیے یقین کریں کہ کاپی میں شروعات اور اختتام دونوں شامل ہیں۔</p>\n<p>جان لیں کہ تصویر کس لیے ہے، کیونکہ یہی ڈاؤن لوڈ فارمیٹ طے کرتا ہے۔ Original فائل کو بالکل رکھتا ہے، PNG شفافیت رکھتا ہے، JPG تصویروں کو چھوٹا کرتا ہے اور WebP جدید کمپیکٹ انتخاب ہے۔</p>\n<p>سافٹ ویئر کے طور پر صرف براؤزر چاہیے۔ ٹول کروم، سفاری، فائر فاکس اور ایج پر چلتا ہے، ڈیسک ٹاپ اور موبائل پر، بغیر کسی ایکسٹینشن کے۔</p>\n<h2 id=\"step-1-paste-the-string\">مرحلہ 1: Base64 اسٹرنگ پیسٹ کریں</h2>\n<p><a href=\"/ur/base64-ko-tasveer-mein-convert-karein/\">Base64 to Image ڈی کوڈر</a> کھولیں اور اسٹرنگ ان پٹ والے حصے میں پیسٹ کریں۔ ڈی کوڈنگ خود بخود شروع ہو جاتی ہے، بغیر کسی بٹن پر کلک کیے۔</p>\n<p>ٹول data:image پیش لاحقے کے ساتھ یا اس کے بغیر اسٹرنگ قبول کرتا ہے۔ ویب صفحے سے مکمل Data URL اور JSON پے لوڈ سے کچی اسٹرنگ دونوں کام کرتی ہیں۔</p>\n<p>URL-safe اسٹرنگ بھی کام کرتی ہیں۔ اگر اسٹرنگ جمع اور سلیش کی بجائے ڈیش اور انڈر اسکور استعمال کرتی ہے تو ڈی کوڈر اس قسم کو پہچان کر درست ڈی کوڈ کرتا ہے۔</p>\n<h2 id=\"step-2-review-preview\">مرحلہ 2: پیش نظارہ اور پیمائش جائزہ لیں</h2>\n<p>ڈی کوڈ شدہ تصویر چیکر بورڈ پس منظر پر دکھائی دیتی ہے، اس کے ابعاد اور فائل سائز ساتھ دکھائے جاتے ہیں۔ جانچیں کہ تصویر وہی ہے جس کی آپ کو توقع تھی۔</p>\n<p>چیکر بورڈ کو احتیاط سے دیکھیں۔ تصویر سے جھانکتے سرمئی اور سفید مربع شفافیت بتاتے ہیں، اور یہی طے کرتا ہے کہ JPG استعمال کرنا محفوظ ہے یا نہیں۔</p>\n<p>ابعاد جانچیں۔ اسٹرنگ سے ڈی کوڈ شدہ چھوٹا آئیکن چھوٹی تصویر ہی ہوتا ہے، اور کوئی ڈاؤن لوڈ فارمیٹ اسے بڑا یا تیز نہیں بنائے گا۔</p>\n<h2 id=\"step-3-choose-format\">مرحلہ 3: ڈاؤن لوڈ فارمیٹ چنیں</h2>\n<p>جب آپ فائل بالکل ویسے ہی چاہتے ہیں جیسے انکوڈ ہوئی تھی تو Original چنیں۔ یہ محفوظ ترین انتخاب ہے، خاص طور پر متحرک GIF اور ویکٹر SVG کے لیے، جو بدلنے پر اپنی خاص خصوصیات کھو دیتے ہیں۔</p>\n<p>جب تصویر میں شفافیت یا تیز کنارے ہوں تو PNG چنیں۔ PNG پکسل بالکل محفوظ رکھتا ہے اور الفا چینل رکھتا ہے، اس لیے لوگو اور آئیکن راؤنڈ ٹرپ سے بچ جاتے ہیں۔</p>\n<p>جب تصویر فوٹو ہو اور آپ سب سے چھوٹی فائل چاہتے ہوں تو JPG چنیں۔ JPG شفافیت گرا دیتا ہے، اس لیے اسے صرف اس وقت استعمال کریں جب چیکر بورڈ پیش نظارہ میں کوئی شفاف حصہ نہ دکھائی دے۔</p>\n<h2 id=\"step-4-download\">مرحلہ 4: تصویر فائل ڈاؤن لوڈ کریں</h2>\n<p>ڈاؤن لوڈ بٹن پر کلک کریں۔ فائل decoded_image کے طور پر محفوظ ہوتی ہے، آپ کے چنے ہوئے فارمیٹ سے میل کھانے والی ایکسٹینشن کے ساتھ، جیسے decoded_image.png یا decoded_image.jpg۔</p>\n<p>فائل کا نام فوراً کچھ معنی خیز رکھیں۔ decoded_image نام کی فائلوں سے بھرا فولڈر الجھن پیدا کرتا ہے، جبکہ company-logo.png جیسا نام مہینوں بعد بھی بتاتا ہے کہ یہ کیا ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائل کھولیں اور یقین کریں کہ وہ درست لگتی ہے۔ ٹول میں پیش نظارہ قابل اعتماد ہے، مگر اصل فائل کی آخری جانچ سیکنڈوں میں ہوتی ہے۔</p>\n<h2 id=\"decoding-without-prefix\">پیش لاحقے کے بغیر اسٹرنگ ڈی کوڈ کرنا</h2>\n<p>کئی اسٹرنگ data:image پیش لاحقے کے بغیر آتی ہیں، خاص طور پر API اور ڈیٹا بیس سے۔ ڈی کوڈر فارمیٹ پہچاننے کے لیے تصویر کا ہیڈر پڑھتا ہے، اس لیے گم شدہ پیش لاحقہ مسئلہ نہیں ہے۔</p>\n<p>کچی اسٹرنگ ویسے ہی پیسٹ کریں۔ ٹول پتا لگاتا ہے کہ بائٹ PNG، JPG، GIF، WebP، SVG، BMP یا ICO فائل بیان کرتے ہیں، اور پتا چلا فارمیٹ پیش نظارے کے ساتھ دکھاتا ہے۔</p>\n<p>اگر فارمیٹ غلط پتا چلے تو فائل ہیڈر خود غیر معمولی ہے۔ اس صورت میں Original کے طور پر ڈاؤن لوڈ کریں، اور بدلنے سے پہلے فائل امیج ویور سے جانچیں۔</p>\n<h2 id=\"decoding-url-safe-strings\">URL-safe اسٹرنگ ڈی کوڈ کرنا</h2>\n<p>URL-safe Base64 جمع کو ڈیش سے اور سلیش کو انڈر اسکور سے بدل دیتا ہے، تاکہ اسٹرنگ ویب پتے میں بغیر ایسکیپ کیے بیٹھ سکے۔ یہ معیاری Base64 جیسی ہی دکھائی دیتی ہے۔</p>\n<p>ڈی کوڈر بغیر کوئی ترتیب بدلے دونوں حروف تہجی قبول کرتا ہے۔ اسٹرنگ پیسٹ کریں اور وہ ڈی کوڈ ہو جاتی ہے، چاہے وہ کسی بھی قسم کی ہو۔</p>\n<p>اگر اسٹرنگ ڈی کوڈ نہ ہو تو دونوں حروف تہجی کے ملے ہونے کو جانچیں۔ جزوی طور پر بدلی ہوئی اسٹرنگ، جس میں کچھ جمع اور کچھ ڈیش ہوں، خراب ہوتی ہے اور ماخذ سے تازہ کاپی چاہیے ہوتی ہے۔</p>\n<h2 id=\"decoding-from-html-css\">HTML یا CSS میں لپٹی اسٹرنگ ڈی کوڈ کرنا</h2>\n<p>اسٹرنگ اکثر اپنے ارد گرد کے کوڈ کے ساتھ کاپی ہوتی ہیں، جیسے Data URL ماخذ والا امیج ٹیگ، یا قیمت لپیٹنے والا CSS url() فنکشن۔</p>\n<p>آپ پورا ٹکڑا پیسٹ کر سکتے ہیں۔ ڈی کوڈر اسٹرنگ کے ارد گرد HTML اقتباس اور CSS url() ریپر برداشت کرتا ہے، اور اندر سے Base64 مواد نکال لیتا ہے۔</p>\n<p>اگر پیسٹ ناکام ہو تو ریپر خود ہٹا دیں۔ base64 کے بعد کوما اور بند اقتباس کے درمیان والا حصہ کاپی کریں، اور وہ صاف اسٹرنگ پیسٹ کریں۔</p>\n<h2 id=\"converting-old-formats\">پرانی BMP یا ICO اسٹرنگ کو WebP میں بدلنا</h2>\n<p>پرانی فیویکن اور بٹ میپ اسٹرنگ BMP یا ICO فائلوں میں ڈی کوڈ ہوتی ہیں، جو بھاری ہوتی ہیں اور جدید ویب پر کم سپورٹ ہوتی ہیں۔ انہیں WebP میں بدلنا دونوں مسائل ایک ساتھ ٹھیک کر دیتا ہے۔</p>\n<p>اسٹرنگ پیسٹ کریں، پیش نظارہ کا انتظار کریں اور ڈاؤن لوڈ فارمیٹ کے طور پر WebP چنیں۔ ٹول ڈی کوڈ شدہ تصویر کو کمپیکٹ جدید فائل میں بدل دیتا ہے۔</p>\n<p>پہلے شفافیت جانچیں۔ ICO فیویکن میں اکثر شفاف حصے ہوتے ہیں، اور WebP انہیں محفوظ رکھتا ہے، اس لیے بدلی ہوئی آئیکن اصل جیسی لگتی ہے۔</p>\n<h2 id=\"decoding-svg-to-png\">SVG اسٹرنگ کو PNG فائل میں ڈی کوڈ کرنا</h2>\n<p>SVG Base64 اسٹرنگ ویکٹر کوڈ میں ڈی کوڈ ہوتی ہے، جو کسی بھی سائز پر صاف ہوتی ہے مگر ہر جگہ قبول نہیں ہوتی۔ کچھ پلیٹفارم ریسٹر تصویر چاہتے ہیں، اور PNG عام انتخاب ہے۔</p>\n<p>اسٹرنگ پیسٹ کریں، یقین کریں کہ پیش نظارہ ویکٹر گرافک درست دکھاتا ہے اور ڈاؤن لوڈ فارمیٹ کے طور پر PNG چنیں۔ ٹول SVG کو اس کے اندرونی ابعاد پر PNG میں رینڈر کرتا ہے۔</p>\n<p>نتیجہ PNG مقررہ سائز کی تصویر ہوتی ہے، اس لیے وہ اصل SVG کی طرح اسکیل نہیں ہوگی۔ اگر منزل کو بڑی تصویر چاہیے تو ڈاؤن لوڈ سے پہلے بڑے سائز پر رینڈر کریں، یا SVG رکھیں۔</p>\n<h2 id=\"troubleshooting-corrupt-strings\">خراب اسٹرنگ کی خرابی دور کرنا</h2>\n<p>ڈی کوڈ نہ ہونے والی اسٹرنگ عام طور پر کٹی ہوئی، بدلی ہوئی یا کبھی تصویر ہی نہیں ہوتی۔ ٹول ٹوٹی فائل بنانے کی بجائے صاف غلطی بتاتا ہے۔</p>\n<p>پہلے اسٹرنگ کی شروعات اور اختتام جانچیں۔ کٹوتی عام طور پر دم کاٹتی ہے، اس لیے درمیان لفظ یا پیڈنگ کے بغیر ختم ہونے والی اسٹرنگ نامکمل کاپی کی علامت ہے۔</p>\n<p>ایسے حروف تلاش کریں جو Base64 میں نہیں ہونے چاہییں۔ اسٹرنگ کے اندر زاویہ بریکٹ، اقتباس یا اضافی پیرامیٹر والا URL سب بتاتے ہیں کہ کاپی نے ارد گرد کا متن بھی پکڑ لیا ہے۔</p>\n<h2 id=\"troubleshooting-svg-error\">SVG انکوڈنگ غلطی کی خرابی دور کرنا</h2>\n<p>SVG انکوڈنگ غلطی اس وقت آتی ہے جب پیسٹ شدہ اسٹرنگ Base64 والی کی بجائے سادہ SVG Data URL ہو۔ اس میں انکوڈ شدہ حروف کی بجائے پڑھنے کے قابل SVG ٹیگ ہوتے ہیں۔</p>\n<p>اسے اسٹرنگ دیکھ کر پہچانیں۔ اگر اس کے اندر svg، path یا rect جیسے الفاظ پڑھ سکیں تو اسٹرنگ URL-encoded SVG کوڈ ہے، Base64 نہیں۔</p>\n<p>فائل لینے کے لیے Data URL سے SVG کوڈ نکالیں، فیصد ایسکیپ ڈی کوڈ کریں اور نتیجہ ٹیکسٹ ایڈیٹر میں .svg فائل کے طور پر محفوظ کریں۔</p>\n<h2 id=\"clearing-and-next\">اگلی اسٹرنگ کے لیے ان پٹ صاف کرنا</h2>\n<p>لمبی اسٹرنگ ہاتھ سے حذف کرنا مشکل ہوتا ہے، اس لیے ٹول ایک کلک میں ان پٹ خالی کرنے والا صاف بٹن دیتا ہے۔ ڈی کوڈ کے درمیان تازہ شروع کرنے کے لیے اسے استعمال کریں۔</p>\n<p>اگلی اسٹرنگ پیسٹ کرنے سے پہلے صاف کریں، بعد میں نہیں۔ لمبی اسٹرنگ پر پیسٹ کرنے سے پرانی کے ٹکڑے رہ سکتے ہیں، جو نئی ڈی کوڈ خراب کر دیتے ہیں۔</p>\n<p>صاف کرنے سے پہلے موجودہ تصویر ڈاؤن لوڈ کریں۔ صاف کرنے سے اسٹرنگ اور پیش نظارہ دونوں ہٹ جاتے ہیں، اور ڈی کوڈ شدہ تصویر اس کے بعد صرف ڈاؤن لوڈ شدہ فائل کے طور پر رہتی ہے۔</p>\n<h2 id=\"re-encoding-the-image\">ڈاؤن لوڈ شدہ تصویر دوبارہ انکوڈ کرنا</h2>\n<p>کبھی ڈی کوڈ شدہ تصویر کو واپس متن کی شکل میں جانا ہوتا ہے، مثال کے طور پر پرانی BMP کو جدید WebP میں بدلنے کے بعد۔ انکوڈر یہ مرحلہ سنبھالتا ہے۔</p>\n<p><a href=\"/ur/tasveer-ko-base64-mein-convert-karein/\">Image to Base64 انکوڈر</a> کھولیں، ڈاؤن لوڈ شدہ فائل اپ لوڈ کریں اور تازہ اسٹرنگ اپنی ضرورت کے آؤٹ پٹ فارمیٹ میں کاپی کریں۔</p>\n<p>تبدیلی سے فائل چھوٹی ہوئی ہو تو نئی اسٹرنگ اصل سے چھوٹی ہوتی ہے۔ دوبارہ انکوڈ کرنے سے پہلے WebP میں بدلی گئی BMP اصل سے ڈرامائی طور پر چھوٹی اسٹرنگ بناتی ہے۔</p>\n<h2 id=\"decoding-from-chat-and-documents\">چیٹ پیغام اور دستاویزات سے تصویریں ڈی کوڈ کرنا</h2>\n<p>چیٹ ایپس اور تعاون کے اوزار کبھی تصویروں کو اپنے پیغام ڈیٹا میں Base64 اسٹرنگ کے طور پر ظاہر کرتے ہیں، خاص طور پر بوٹ، ویب ہک اور برآمد شدہ گفتگو میں۔ کاپی شدہ پے لوڈ ڈی کوڈ کر کے تصویر واپس مل سکتی ہے۔</p>\n<p>چیٹ برآمد سے کاپی کرتے وقت اسٹرنگ کے لائنوں میں بٹنے یا JSON ایسکیپنگ میں لپٹے ہونے پر نظر رکھیں۔ سلیش اور اقتباس سے پہلے بیک سلیش ایسکیپنگ کی نشانیاں ہیں، اسٹرنگ کا حصہ نہیں، اور ڈی کوڈ سے پہلے انہیں ہٹانا ہوتا ہے۔</p>\n<p>دستاویزات بھی ایسا ہی ماخذ ہیں۔ برآمد شدہ Word یا ڈیزائن فائل اپنے XML کے اندر Base64 بلاک کے طور پر ایمبیڈ شدہ تصویر رکھ سکتی ہے، اور وہ بلاک کاپی کرنے سے تصویر سیدھا مل جاتی ہے۔</p>\n<h2 id=\"quick-reference-checklist\">فوری حوالہ چیک لسٹ</h2>\n<p>مکمل اسٹرنگ پیسٹ کریں، شفافیت کے لیے پیش نظارہ اور چیکر بورڈ جانچیں، Original، PNG، JPG یا WebP چنیں اور درست ایکسٹینشن کے ساتھ decoded_image کے طور پر ڈاؤن لوڈ کریں۔</p>\n<p>اسٹرنگ کے درمیان ان پٹ صاف کریں، ڈاؤن لوڈ فوراً نام بدلیں اور نئی فائل آزمانے تک اصل اسٹرنگ رکھیں۔</p>\n<p>مکمل پس منظر کے لیے <a href=\"/ur/blog/base64-ko-tasveer-rehnumai/\">Base64 to Image: Complete Guide</a> پڑھیں، اور کارکردگی موازنے کے لیے <a href=\"/ur/blog/base64-vs-tasveer-files/\">Base64 vs Image Files: Performance and Use Cases</a> دیکھیں۔</p>\n";

